def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for quick access
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x - 1, y - 1)] = value

    # Initialize a 3D DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]

    # Base case: starting point
    dp[0][0][0] = grid[(0, 0)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(min(i + j + 1, N)):
                l = i + j - k
                if i > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1])
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k])
                if j > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1])
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k])
                if dp[i][j][k] == -float('inf'):
                    continue
                if i == k and j == l:
                    dp[i][j][k] += grid[(i, j)]
                else:
                    dp[i][j][k] += grid[(i, j)] + grid[(k, l)]

    # The result is the maximum value in the last layer of the DP table
    return max(dp[N - 1][N - 1])

