        # Calculate the correct checksum
        correct_checksum = calculate_checksum(isbn[:-1])

        # Compare the provided checksum with the calculated one
        if checksum == correct_checksum:
            return "Right"
        else:
            return f"{prefix}-{group}-{registrant}-{correct_checksum}"

    except Exception as e:
        raise ValueError(f"Error verifying ISBN: {e}")

